```js
#!/usr/bin/env node
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = __dirname;
const MANIFEST_NAME = 'backup-manifest.json';
const MANIFEST_PATH = path.join(ROOT, MANIFEST_NAME);

function collectFiles(dir, prefix, seenDirs, files) {
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    if (entry.name.startsWith('.')) continue;
    const relativePath = prefix ? `${prefix}/${entry.name}` : entry.name;
    const absolutePath = path.join(dir, entry.name);
    let stats;
    try {
      stats = fs.statSync(absolutePath);
    } catch {
      continue;
    }
    if (stats.isDirectory()) {
      let realPath;
      try { realPath = fs.realpathSync(absolutePath); } catch { realPath = absolutePath; }
      if (seenDirs.has(realPath)) continue;
      seenDirs.add(realPath);
      collectFiles(absolutePath, relativePath, seenDirs, files);
      continue;
    }
    if (!stats.isFile()) continue;
    if (relativePath === MANIFEST_NAME) continue;
    files.push(relativePath);
  }
}

function listWorkspaceFiles() {
  const files = [];
  collectFiles(ROOT, '', new Set([fs.realpathSync(ROOT)]), files);
  return files.sort();
}

function writeManifest(files) {
  const payload = { files };
  fs.writeFileSync(MANIFEST_PATH, `${JSON.stringify(payload, null, 2)}\n`);
}

function verifyManifest() {
  if (!fs.existsSync(MANIFEST_PATH)) { console.error('FAIL: backup-manifest.json not found'); return false; }
  let manifest;
  try { manifest = JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8')); }
  catch (error) { console.error(`FAIL: backup-manifest.json is not valid JSON: ${error.message}`); return false; }
  if (!manifest || !Array.isArray(manifest.files)) { console.error('FAIL: manifest has no "files" array'); return false; }
  const expected = listWorkspaceFiles();
  const actual = manifest.files;
  const problems = [];
  if (actual.includes(MANIFEST_NAME)) problems.push('manifest lists itself');
  if (actual.some((name) => name.split('/').some((part) => part.startsWith('.')))) problems.push('manifest lists hidden files');
  if (actual.some((name) => name !== MANIFEST_NAME && !fs.existsSync(path.join(ROOT, name)))) problems.push('manifest lists files that no longer exist');
  const sorted = [...actual].sort();
  if (JSON.stringify(sorted) !== JSON.stringify(actual)) problems.push('files are not sorted');
  if (JSON.stringify(actual) !== JSON.stringify(expected)) problems.push(`files mismatch: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  if (problems.length) { problems.forEach(p => console.error(`FAIL: ${p}`)); return false; }
  console.log(`OK: ${actual.length} files recorded`);
  return true;
}

const mode = process.argv[2];
if (mode === '--verify' || mode === 'verify') {
  process.exit(verifyManifest() ? 0 : 1);
}
const files = listWorkspaceFiles();
writeManifest(files);
console.log(`Wrote ${MANIFEST_NAME} with ${files.length} files: ${files.join(', ')}`);
```

