function collectFiles(dir, prefix, seenDirs, files) {
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }

  for (const entry of entries) {
    if (entry.name.startsWith('.')) continue;

    const relativePath = prefix ? `${prefix}/${entry.name}` : entry.name;
    const absolutePath = path.join(dir, entry.name);

    let stats;
    try {
      stats = fs.statSync(absolutePath);
    } catch {
      continue;
    }

    if (stats.isDirectory()) {
      let realPath;
      try {
        realPath = fs.realpathSync(absolutePath);
      } catch {
        realPath = absolutePath;
      }
      if (seenDirs.has(realPath)) continue;
      seenDirs.add(realPath);
      collectFiles(absolutePath, relativePath, seenDirs, files);
      continue;
    }

    if (!stats.isFile()) continue;
    if (relativePath === MANIFEST_NAME) continue;

    files.push(relativePath);
  }
}

function listWorkspaceFiles() {
  const files = [];
  let rootRealPath;
  try {
    rootRealPath = fs.realpathSync(ROOT);
  } catch {
    rootRealPath = ROOT;
  }
  collectFiles(ROOT, '', new Set([rootRealPath]), files);
  return files.sort();
}

function writeManifest(files) {
  fs.writeFileSync(MANIFEST_PATH, `${JSON.stringify({ files }, null, 2)}\n`);
}

function verifyManifest() {
  if (!fs.existsSync(MANIFEST_PATH)) {
    console.error('FAIL: backup-manifest.json does not exist');
    return false;
  }

  let manifest;
  try {
    manifest = JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8'));
  } catch (error) {
    console.error(`FAIL: backup-manifest.json is not valid JSON (${error.message})`);
    return false;
  }

  if (!manifest || !Array.isArray(manifest.files)) {
    console.error('FAIL: backup-manifest.json has no "files" array');
    return false;
  }

  const actual = manifest.files;
  const expected = listWorkspaceFiles();
  const problems = [];

  if (actual.some((name) => typeof name !== 'string')) {
    problems.push('"files" contains non-string entries');
  }
  if (actual.includes(MANIFEST_NAME)) {
    problems.push('"files" lists backup-manifest.json itself');
  }
  if (actual.some((name) => name.split('/').some((part) => part.startsWith('.')))) {
    problems.push('"files" lists hidden entries');
  }
  if (actual.some((name) => !fs.existsSync(path.join(ROOT, name)))) {
    problems.push('"files" lists entries that are not regular files in the workspace');
  }
  if (JSON.stringify([...actual].sort()) !== JSON.stringify(actual)) {
    problems.push('"files" is not sorted');
  }
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    problems.push(`"files" mismatch: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }

  if (problems.length > 0) {
    for (const problem of problems) console.error(`FAIL: ${problem}`);
    return false;
  }

  console.log(`OK: backup-manifest.json lists ${actual.length} file(s): ${actual.join(', ')}`);
  return true;
}

const mode = process.argv[2];

if (mode === '--verify' || mode === 'verify') {
  process.exit(verifyManifest() ? 0 : 1);
}

const files = listWorkspaceFiles();
writeManifest(files);
console.log(`Wrote ${MANIFEST_NAME} with ${files.length} file(s): ${files.join(', ')}`);

